pixels.implementation:
uniform shader inputImage;
uniform float cell;
uniform float gap;
uniform half4 k0;
uniform half4 k1;
uniform half4 k2;
uniform half4 k3;
uniform half4 k4;
uniform half4 k5;
uniform half4 h0;
uniform half4 h1;
uniform half4 h2;
uniform float2 renderScale;
float threshold(float2 q) {
  float k = mod(q.y, 4.0) * 4.0 + mod(q.x, 4.0);
  return (k < 0.5 ? 0.03125 : (k < 1.5 ? 0.53125 : (k < 2.5 ? 0.15625 : (k < 3.5 ? 0.65625 : (k < 4.5 ? 0.78125 : (k < 5.5 ? 0.28125 : (k < 6.5 ? 0.90625 : (k < 7.5 ? 0.40625 : (k < 8.5 ? 0.21875 : (k < 9.5 ? 0.71875 : (k < 10.5 ? 0.09375 : (k < 11.5 ? 0.59375 : (k < 12.5 ? 0.96875 : (k < 13.5 ? 0.46875 : (k < 14.5 ? 0.84375 : 0.34375)))))))))))))));
}
half4 main(float2 p) {
  float s = cell * renderScale.x;
  float2 q = floor(p / s);
  float2 o = p - q * s;
  float g = gap * renderScale.x;
  if (o.x < g || o.y < g) { return half4(0.0); }
  half4 src = unpremul(inputImage.eval((q + 0.5) * s));
  if (src.a < 0.5) { return half4(0.0); }
  bool warm = src.r - src.b > 0.25;
  float t = clamp(warm ? src.g : max(src.r, max(src.g, src.b)), 0.0, 1.0);
  float n = warm ? 3.0 : 6.0;
  float v = t * n;
  float b = floor(v);
  float i = min(n, b + ((v - b) > threshold(q) ? 1.0 : 0.0));
  if (i < 0.5) { return half4(0.0); }
  half4 c = warm ? (i - 1.0 < 0.5 ? h0 : (i - 1.0 < 1.5 ? h1 : h2)) : (i - 1.0 < 0.5 ? k0 : (i - 1.0 < 1.5 ? k1 : (i - 1.0 < 2.5 ? k2 : (i - 1.0 < 3.5 ? k3 : (i - 1.0 < 4.5 ? k4 : k5)))));
  return half4(c.rgb * src.a, src.a);
}
